# Initially generated by GitHub Copilot.


def explanation_for_path(path_parts):
    if not path_parts:
        return None
    family, *rest = path_parts
    if family == "slh-letter-count":
        return _slh_letter_count_explanation(rest)
    if family == "stack":
        return _stack_explanation(rest)
    if family == "non-note":
        return _non_note_explanation(rest)
    assert False, path_parts


def _slh_letter_count_explanation(path_parts):
    assert len(path_parts) == 1, path_parts
    count = int(path_parts[0])
    noun = "special letter" if count == 1 else "special letters"
    return (
        f"that the word contains {count} {noun}, where special means small, large, "
        "or hung"
    )


def _stack_explanation(path_parts):
    assert len(path_parts) == 1, path_parts
    stack_summary = path_parts[0]
    return _STACK_EXPLANATIONS.get(
        stack_summary, _generic_stack_explanation(stack_summary)
    )


def _generic_stack_explanation(stack_summary):
    return (
        "that the slh-word template occurs in the local wrapper context "
        f"{stack_summary}"
    )


def _non_note_explanation(path_parts):
    assert len(path_parts) == 2, path_parts
    count = int(path_parts[0])
    code_str = path_parts[1]
    assert len(code_str) == count, path_parts
    noun = "special letter" if count == 1 else "special letters"
    code_description = _code_string_description(code_str)
    return (
        f"that the word is not itself inside a note, contains {count} {noun}, "
        f"and has special-letter code string {code_str}, i.e. {code_description}"
    )


def _code_string_description(code_str):
    decoded = tuple(_CODE_DESCRIPTIONS[char] for char in code_str)
    if len(decoded) == 1:
        return decoded[0]
    if len(decoded) == 2:
        return f"{decoded[0]} and then {decoded[1]}"
    return ", ".join(decoded[:-1]) + f", and then {decoded[-1]}"


_STACK_EXPLANATIONS = {
    "None": (
        "that the slh-word template occurs directly in the running text, with no "
        "relevant local wrapper context"
    ),
    "doc-part-n": (
        "that the slh-word template occurs inside a documentation line rather than "
        "directly in the running text"
    ),
    "kq-ketiv": (
        "that the slh-word template occurs on the ketiv side of a ketiv/qere case"
    ),
    "scrdfftar-note": (
        "that the slh-word template occurs inside a scroll-difference note"
    ),
}


